// Lightweight 3D globe: lat/long projection, depth-shaded grid, rotating nodes and arcs.
$$('.world-canvas').forEach(canvas=>{const ctx=canvas.getContext('2d');if(!ctx)return;let w=1,h=1,dpr=1,rotation=.3,visible=true,last=0;const points=[];for(let lat=-75;lat<=75;lat+=10)for(let lng=-180;lng<180;lng+=10)points.push([lat*Math.PI/180,lng*Math.PI/180]);const nodes=[['LONDON',51.5,-.1],['NEW YORK',40.7,-74],['DUBAI',25.2,55.3],['RIYADH',24.7,46.7],['DOHA',25.3,51.5],['MUSCAT',23.6,58.4]];
function size(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(w*dpr));canvas.height=Math.max(1,Math.round(h*dpr));ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
function project(lat,lng){const x=Math.cos(lat)*Math.sin(lng+rotation),y=-Math.sin(lat),z=Math.cos(lat)*Math.cos(lng+rotation);const tilt=.22;return[x,y*Math.cos(tilt)-z*Math.sin(tilt),y*Math.sin(tilt)+z*Math.cos(tilt)];}
function draw(){ctx.clearRect(0,0,w,h);const radius=Math.min(w*.37,h*.38),cx=w*.51,cy=h*.43;const glow=ctx.createRadialGradient(cx-radius*.3,cy-radius*.4,0,cx,cy,radius*1.2);glow.addColorStop(0,'#9ac18a22');glow.addColorStop(.8,'#6f987416');glow.addColorStop(1,'#33583e00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(cx,cy,radius*1.2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#a6c18b40';ctx.lineWidth=.7;ctx.beginPath();ctx.arc(cx,cy,radius,0,Math.PI*2);ctx.stroke();
for(let lat=-60;lat<=60;lat+=30){let on=false;ctx.beginPath();for(let lng=-180;lng<=180;lng+=3){const [x,y,z]=project(lat*Math.PI/180,lng*Math.PI/180);if(z>0){if(!on)ctx.moveTo(cx+x*radius,cy+y*radius);else ctx.lineTo(cx+x*radius,cy+y*radius);on=true;}else on=false;}ctx.strokeStyle='#b8ce9e30';ctx.stroke();}
for(let lng=-180;lng<180;lng+=30){let on=false;ctx.beginPath();for(let lat=-90;lat<=90;lat+=3){const[x,y,z]=project(lat*Math.PI/180,lng*Math.PI/180);if(z>0){if(!on)ctx.moveTo(cx+x*radius,cy+y*radius);else ctx.lineTo(cx+x*radius,cy+y*radius);on=true;}else on=false;}ctx.strokeStyle='#b8ce9e30';ctx.stroke();}
points.forEach(([lat,lng])=>{const[x,y,z]=project(lat,lng);if(z<0)return;ctx.fillStyle=`rgba(186,210,152,${.13+z*.45})`;ctx.beginPath();ctx.arc(cx+x*radius,cy+y*radius,.8+z*.45,0,Math.PI*2);ctx.fill();});
const visibleNodes=[];nodes.forEach(([name,lat,lng])=>{const[x,y,z]=project(lat*Math.PI/180,lng*Math.PI/180);if(z<.05)return;visibleNodes.push({name,x:cx+x*radius,y:cy+y*radius,z});});if(visibleNodes.length>1){const a=visibleNodes[0];visibleNodes.slice(1).forEach(b=>{ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.quadraticCurveTo((a.x+b.x)/2,Math.min(a.y,b.y)-radius*.3,b.x,b.y);ctx.strokeStyle='#f49f6555';ctx.lineWidth=.8;ctx.stroke();});}
visibleNodes.forEach((p,i)=>{ctx.fillStyle='#f99e70';ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f99e7055';ctx.beginPath();ctx.arc(p.x,p.y,7,0,Math.PI*2);ctx.stroke();if(p.name==='LONDON'||p.name==='NEW YORK'||p.name==='DUBAI'){ctx.font='7px Arial';ctx.fillStyle='#d9e2c2';ctx.fillText(p.name,p.x+10,p.y+(p.name==='DUBAI'?16:-7));}});ctx.strokeStyle='#c1cda728';ctx.beginPath();ctx.ellipse(cx,cy,radius*1.18,radius*.31,-.33,0,Math.PI*2);ctx.stroke();}
function frame(t){if(!visible||document.hidden){last=t;requestAnimationFrame(frame);return;}if(t-last>35){rotation+=.003;draw();last=t;}requestAnimationFrame(frame);}new ResizeObserver(size).observe(canvas);if('IntersectionObserver'in window)new IntersectionObserver(e=>{visible=e[0].isIntersecting;},{rootMargin:'100px'}).observe(canvas);size();if(!reduce)requestAnimationFrame(frame);
});
// Sample rates are illustrative content approved for this preview, not live offers.
const rates={GBP:[20,18,16],USD:[20,18,16],AED:[80,72,64],SAR:[85,76,68],QAR:[80,72,64],OMR:[8,7,6]};
function money(n,c){return new Intl.NumberFormat('en-GB',{style:'currency',currency:c,maximumFractionDigits:0}).format(n);}
function refreshPlans(){const c=$('#pricing-region')?.value;if(!c)return;$$('.plan-card').forEach((el,i)=>{const count=[4,8,12][i],rate=rates[c][i];el.querySelector('[data-price]').textContent=money(rate,c);el.querySelector('[data-total]').textContent=money(rate*count,c);el.querySelector('[data-currency]').textContent=c;const a=el.querySelector('a.button'),u=new URL(a.href);u.searchParams.set('country',$('#pricing-region').selectedOptions[0].dataset.country||'Other countries');a.href=u.pathname+u.search;});if($('#planner-link')){$('#planner-link').dataset.currency=c;const u=new URL($('#planner-link').href);u.searchParams.set('country',$('#pricing-region').selectedOptions[0].dataset.country||'Other countries');$('#planner-link').href=u.pathname+u.search;refreshPlanner();}}
$('#pricing-region')?.addEventListener('change',refreshPlans);
function refreshPlanner(){if(!$('#planner-frequency'))return;const n=Number($('#planner-frequency').value),weeks=Number($('#planner-weeks').value),total=n*weeks,c=$('#planner-link').dataset.currency||'USD',rate=rates[c][Math.min(n-1,2)];$('#planner-total').textContent=total;$('#planner-price').textContent=money(rate*total,c);$('#planner-unit').textContent=money(rate,c);const u=new URL($('#planner-link').href);u.searchParams.set('plan',`${n} lessons per week for ${weeks} weeks (${total} lessons; illustrative ${money(total*rate,c)})`);$('#planner-link').href=u.pathname+u.search;}
$('#planner-frequency')?.addEventListener('change',refreshPlanner);$('#planner-weeks')?.addEventListener('change',refreshPlanner);refreshPlanner();
