const answers={subjects:'Explore maths, sciences, English, languages, humanities, computing, and business subjects from primary to Grade 12 / FSc. Exact subject and tutor availability are confirmed individually.',pricing:'The pricing pages show illustrative sample lesson rates and package totals. They are placeholders for this preview. Request a personal quote before arranging lessons.',international:'Yes. Choose the UK, USA, UAE, Saudi Arabia, Qatar, Oman, or Other countries. Add your own time zone and preferred lesson window to your enquiry.'};$$('[data-help]').forEach(b=>b.addEventListener('click',()=>{$('#help-answer').textContent=answers[b.dataset.help];}));
